-- Source-backed inventory expansion for thinner Central Illinois markets.
-- Imported profiles remain unclaimed, unverified, unfeatured, unsponsored and carry no imported ratings/reviews.

create temp table _cilp_inventory_business_stage (
  slug text primary key,
  name text not null,
  abbr text,
  city_slug text not null,
  city text not null,
  phone text,
  email text,
  website text,
  description text not null,
  address_text text,
  postal_code text,
  location_type text,
  source_name text not null,
  source_url text not null,
  attributes jsonb not null default '{}'::jsonb,
  service_area_only boolean not null default false
) on commit drop;


select '6673621d-b359-4c17-a984-c8f50d914eb3'::uuid,s.slug,s.name,s.abbr,l.id,s.phone,s.email,s.website,s.description,'published',now(),s.address_text,s.source_name,s.source_url,now(),0,0,false,false,false,s.attributes
from _cilp_inventory_business_stage s
join public.locations l on l.tenant_id='6673621d-b359-4c17-a984-c8f50d914eb3'::uuid and l.slug=s.city_slug and l.is_active=true
on conflict (tenant_id,slug) do update set name=excluded.name,abbr=excluded.abbr,primary_location_id=excluded.primary_location_id,phone=excluded.phone,email=excluded.email,website=excluded.website,description=excluded.description,status='published',published_at=coalesce(public.businesses.published_at,now()),address_text=excluded.address_text,source_name=excluded.source_name,source_url=excluded.source_url,source_checked_at=excluded.source_checked_at,attributes=coalesce(public.businesses.attributes,'{}'::jsonb)||excluded.attributes,updated_at=now();

select '6673621d-b359-4c17-a984-c8f50d914eb3'::uuid,b.id,l.id,s.city||' location',s.location_type,true,true,false,s.address_text,s.city,'IL',s.postal_code,s.phone,s.email,s.source_name,s.source_url,now()
from _cilp_inventory_business_stage s
join public.businesses b on b.tenant_id='6673621d-b359-4c17-a984-c8f50d914eb3'::uuid and b.slug=s.slug
join public.locations l on l.tenant_id=b.tenant_id and l.slug=s.city_slug and l.is_active=true
where s.address_text is not null and not exists (select 1 from public.business_locations bl where bl.business_id=b.id and bl.city=s.city and bl.address_text=s.address_text);

select b.id,l.id from _cilp_inventory_business_stage s
join public.businesses b on b.tenant_id='6673621d-b359-4c17-a984-c8f50d914eb3'::uuid and b.slug=s.slug
join public.locations l on l.tenant_id=b.tenant_id and l.slug=s.city_slug and l.is_active=true
where s.service_area_only=true on conflict do nothing;

create temp table _cilp_inventory_category_stage (business_slug text not null,category_slug text not null,is_primary boolean not null default false,primary key (business_slug,category_slug)) on commit drop;

select b.id,c.id,s.is_primary from _cilp_inventory_category_stage s
join public.businesses b on b.tenant_id='6673621d-b359-4c17-a984-c8f50d914eb3'::uuid and b.slug=s.business_slug
join public.categories c on c.tenant_id=b.tenant_id and c.slug=s.category_slug and c.is_active=true
on conflict (business_id,category_id) do nothing;

-- Bolen Robinson & Ellis already exists; enrich the canonical profile instead of creating a duplicate.
update public.businesses set website='https://brelaw.com',description='Full-service Decatur law firm with attorneys whose published practice areas include criminal defense, family law, personal injury, probate, civil litigation and workers'' compensation.',source_name='Decatur Bar Association / current firm profile',source_url='https://decaturbar.org/directory/',source_checked_at=now(),updated_at=now()
where tenant_id='6673621d-b359-4c17-a984-c8f50d914eb3'::uuid and slug='bolen-robinson-ellis-decatur';
select b.id,c.id,false from public.businesses b join public.categories c on c.tenant_id=b.tenant_id and c.slug in ('criminal-defense','family-law','personal-injury','probate','civil-litigation','workers-compensation','dui') and c.is_active=true
where b.tenant_id='6673621d-b359-4c17-a984-c8f50d914eb3'::uuid and b.slug='bolen-robinson-ellis-decatur'
on conflict (business_id,category_id) do nothing;
